def v_3dinfo_outputs(params: V3dinfo, execution: Execution) -> V3dinfoOutputs:
    """Build the V3dinfoOutputs object for this tool."""
    root_v: OutputPathType = execution.output_file(".")
    return V3dinfoOutputs(
        root=root_v,
        info=[],
    )

def v_3dinfo_execute(params: V3dinfo, runner: Runner | None = None) -> V3dinfoOutputs:
    """
    3dinfo

    Prints out sort-of-useful information from a 3D dataset's header

    Author: AFNI Developers

    URL: https://afni.nimh.nih.gov/

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    v_3dinfo_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(V_3DINFO_METADATA)
    execution.params(params)
    args = v_3dinfo_cargs(params, execution)
    out = v_3dinfo_outputs(params, execution)
    execution.run(args, handle_stdout=lambda s: out.info.append(s))
    return out

